import csv
import io
import re


def _fallback_reader(text):
    rows = []
    row = []
    field = []
    quoted = False
    field_started = False
    i = 0
    length = len(text)

    while i < length:
        char = text[i]

        if quoted:
            if char == '"':
                if i + 1 < length and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                quoted = False
                i += 1
                continue
            field.append(char)
            i += 1
            continue

        if char == '"' and not field_started:
            quoted = True
            field_started = True
            i += 1
            continue

        if char == ',':
            row.append("".join(field))
            field = []
            field_started = False
            i += 1
            continue

        if char == "\r" or char == "\n":
            row.append("".join(field))
            rows.append(row)
            row = []
            field = []
            field_started = False
            if char == "\r" and i + 1 < length and text[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue

        field.append(char)
        field_started = True
        i += 1

    if field or row or field_started or (length > 0 and text[-1] == ","):
        row.append("".join(field))
        rows.append(row)

    return rows


def _read_records(text):
    try:
        csv.field_size_limit(100000000)
    except (OverflowError, AttributeError):
        pass

    try:
        return list(csv.reader(
            io.StringIO(text, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=False,
            strict=False
        ))
    except (csv.Error, ValueError):
        return _fallback_reader(text)


def _normalized_name(value):
    value = value.lstrip("\ufeff").strip().lower()
    return re.sub(r"[^a-z0-9]+", "", value)


def _header_score(row):
    expected = {
        "date", "time", "qty", "quantity", "productid", "price",
        "producttype", "productdescription", "url", "comments", "comment"
    }
    normalized = [_normalized_name(value) for value in row]
    score = sum(1 for value in normalized if value in expected)

    positional = [
        {"date"},
        {"time"},
        {"qty", "quantity"},
        {"productid"},
        {"price"},
        {"producttype"},
        {"productdescription"},
        {"url"},
        {"comments", "comment"}
    ]
    for index, names in enumerate(positional):
        if index < len(normalized) and normalized[index] in names:
            score += 2
    return score


def _find_header(records):
    best_index = None
    best_score = -1

    for index, row in enumerate(records):
        score = _header_score(row)
        if score > best_score:
            best_index = index
            best_score = score
        if score >= 20:
            return index

    if best_index is not None and best_score >= 6:
        return best_index

    for index, row in enumerate(records):
        if any(value.strip() for value in row):
            return index
    return None


def _looks_like_url(value):
    return bool(re.match(r"^\s*(?:https?://|ftp://|www\.)", value, re.I))


def _description_boundary(parts):
    if len(parts) <= 2:
        return 1

    for index in range(1, len(parts)):
        value = parts[index].strip()
        if len(value) >= 35:
            return index
        if re.search(r"[.!?](?:\s|$)", value):
            return index
        if re.match(
            r"^(?:the|this|these|those|a|an|our|with|made|designed|crafted|built|"
            r"great|for|add|let|from|enjoy|featuring)\b",
            value,
            re.I
        ):
            return index
    return 1


def _repair_row(row, width):
    values = ["" if value is None else str(value) for value in row]

    if len(values) == width:
        return values

    if len(values) < width:
        return values + [""] * (width - len(values))

    url_indices = [
        index for index, value in enumerate(values)
        if _looks_like_url(value)
    ]

    if url_indices:
        url_index = url_indices[-1]
        if url_index >= 7:
            variable = values[5:url_index]
            if len(variable) >= 2:
                boundary = _description_boundary(variable)
                product_type = ",".join(variable[:boundary])
                description = ",".join(variable[boundary:])
                comments = ",".join(values[url_index + 1:])
                repaired = (
                    values[:5]
                    + [product_type, description, values[url_index], comments]
                )
                if len(repaired) == width:
                    return repaired

    return values[:width - 1] + [",".join(values[width - 1:])]


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    records = _read_records(raw_csv)
    header_index = _find_header(records)

    if header_index is None:
        return {"columns": [], "rows": []}

    width = 9
    header = _repair_row(records[header_index], width)
    if header:
        header[0] = header[0].lstrip("\ufeff")

    rows = []
    for row in records[header_index + 1:]:
        rows.append(_repair_row(row, width))

    return {"columns": header, "rows": rows}
